window.__reformedWorks["schaff_creeds3_24"] = {"id":"schaff_creeds3_24","a":"Schaff, Philip","t":"Easter Litany of the Moravian Church. A.D. 1749.","u":"https://ccel.org/ccel/schaff/creeds3","c":[{"t":"Easter Litany of the Moravian Church. A.D. 1749.","s":[{"t":"","p":["[This is the chief Confession of the Church of the United Brethren, commonly called the Moravians. It was originally composed in German, and was translated and slightly modified in 1749. The text is taken from the Liturgienbuch der Evangelischen Brüdergemeine, Gnadau, 1873. It has been kindly prepared in both languages for this work by my friend, the Rt. Rev. Edmund de Schweinitz, S.T.D., Bishop of the Moravian Church, Bethlehem, Pa.]"]}]}]};
